assets:
// GET /api/v1/assets: every machine with live status, latest signals, active order, open downtime
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

msg.payload = await lib.assetViews(null, null);
msg.statusCode = 200;
return [msg, null];

asset:
// GET /api/v1/assets/:asset_code
const lib = global.get('lib');
const db = global.get('db');
if (!global.get('mfAuthorize')(msg.req)) {
    msg.statusCode = 401; msg.payload = { error: 'unauthorized' };
    return [msg, null];
}
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };

const list = await lib.assetViews(null, String(msg.req.params.asset_code));
