health:
// GET /api/v1/health: public (uptime monitors), no token needed
const db = global.get('db');
msg.headers = { 'content-type': 'application/json', 'cache-control': 'no-store' };
try {
    const r = await db.query('SELECT now() AS db_time');
    msg.statusCode = 200;
    msg.payload = { status: 'ok', service: 'manufaction', version: env.get('MF_VERSION') || '2.0.0', db_time: r.rows[0].db_time };
} catch (e) {
    msg.statusCode = 503;
    msg.payload = { error: 'database_unavailable' };
}
return [msg, null];
